     1	export interface Customer {
     2	  yearsWithMHPCO: number;
     3	}
     4	
     5	export interface Item {
     6	  type: string;
     7	  material?: string;
     8	  enchantment?: number;
     9	  cursed?: boolean;
    10	}
    11	
    12	// One entry of the MHPCO price list. The two published figures are quoted
    13	// independently: the office prints them side by side and has never promised that one
    14	// follows the other, so neither is derived from the other here.
    15	interface PriceListEntry {
    16	  insuranceValue: number;
    17	  basePremium: number;
    18	}
    19	
    20	// The MHPCO price list: the single statement of which item types the office insures at
    21	// all and what each of them is worth and costs. Main items are listed individually.
    22	const MAIN_ITEM_PRICE_LIST: Record<string, PriceListEntry> = {
    23	  sword: { insuranceValue: 1000, basePremium: 100 },
    24	  amulet: { insuranceValue: 600, basePremium: 60 },
    25	  staff: { insuranceValue: 800, basePremium: 80 },
    26	  potion: { insuranceValue: 400, basePremium: 40 },
    27	};
    28	
    29	// Components (e.g. runes, moonstones) are not individually price-listed: they all share
    30	// one tariff, so the component roster is the single source of which types are components
    31	// and what each of them is worth and costs.
    32	const COMPONENT_TYPES = ["rune", "moonstone"];
    33	const COMPONENT_PRICE: PriceListEntry = { insuranceValue: 250, basePremium: 25 };
    34	
    35	const PRICE_LIST: Record<string, PriceListEntry> = {
    36	  ...MAIN_ITEM_PRICE_LIST,
    37	  ...Object.fromEntries(COMPONENT_TYPES.map((type) => [type, COMPONENT_PRICE])),
    38	};
    39	
    40	// What the MHPCO is willing to insure at all: only item types on its price list. The
    41	// acceptance rule is enforced at the lookup every price enquiry must pass through, so no
    42	// part of a declined cover can be priced or covered by any route.
    43	function listedPrice(type: string): PriceListEntry {
    44	  const price = PRICE_LIST[type];
    45	  if (price === undefined) {
    46	    throw new Error(`MHPCO does not insure items of type "${type}"`);
    47	  }
    48	  return price;
    49	}
    50	
    51	const BLOCK_SIZE = 3;
    52	const BLOCK_BASE_PREMIUM = 60;
    53	
    54	// MHPCO reading of "alike": two items are alike exactly when their types match,
    55	// not merely when they belong to the same family (rune-y, gemstone-y).
    56	function countAlikeItems(items: Item[]): Map<string, number> {
    57	  const counts = new Map<string, number>();
    58	  for (const item of items) {
    59	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
    60	  }
    61	  return counts;
    62	}
    63	
    64	// A building block is offered for exactly 3 alike components.
    65	function blockOfferApplies(type: string, count: number): boolean {
    66	  return COMPONENT_TYPES.includes(type) && count === BLOCK_SIZE;
    67	}
    68	
    69	function typeBasePremium(type: string, count: number): number {
    70	  if (blockOfferApplies(type, count)) {
    71	    return BLOCK_BASE_PREMIUM;
    72	  }
    73	  return count * listedPrice(type).basePremium;
    74	}
    75	
    76	function policyBasePremium(items: Item[]): number {
    77	  let total = 0;
    78	  for (const [type, count] of countAlikeItems(items)) {
    79	    total += typeBasePremium(type, count);
    80	  }
    81	  return total;
    82	}
    83	
    84	const CURSE_SURCHARGE = 0.5;
    85	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
    86	const SURCHARGED_ENCHANTMENT_LEVEL = 5;
    87	
    88	// An item that carries no enchantment level at all is not enchanted: the MHPCO rates it
    89	// at level 0. Runes and moonstones are the usual such items. Both the premium-side and
    90	// the claim-side enchantment clauses read a level through here, so neither can disagree
    91	// with the other about what an unenchanted item is.
    92	function enchantmentLevel(item: Item): number {
    93	  return item.enchantment ?? 0;
    94	}
    95	
    96	// The enchantment level from which the MHPCO rates an item as a heightened risk worth a
    97	// premium surcharge. Deliberately a lower bar than the level at which the claim side
    98	// halves a reimbursement: charging more for enchantment and paying out less for it are
    99	// two clauses with their own thresholds, and neither follows the other when it moves.
   100	function isEnchantedEnoughToSurcharge(item: Item): boolean {
   101	  return enchantmentLevel(item) >= SURCHARGED_ENCHANTMENT_LEVEL;
   102	}
   103	
   104	// Each risk factor the MHPCO recognises contributes its own rate; a cursed and
   105	// highly enchanted item is assessed both surcharges.
   106	function riskSurchargeRate(item: Item): number {
   107	  return (
   108	    (item.cursed === true ? CURSE_SURCHARGE : 0) +
   109	    (isEnchantedEnoughToSurcharge(item) ? HIGH_ENCHANTMENT_SURCHARGE : 0)
   110	  );
   111	}
   112	
   113	// Item-scoped risk surcharges are assessed against the affected item's own listed
   114	// base premium -- the block offer discounts the policy base premium only and does not
   115	// lower the surcharge base. Each item is rated separately and the results are summed.
   116	function itemScopedSurcharges(items: Item[]): number {
   117	  return items.reduce(
   118	    (total, item) => total + listedPrice(item.type).basePremium * riskSurchargeRate(item),
   119	    0,
   120	  );
   121	}
   122	
   123	const FIRST_INSURANCE_SURCHARGE = 0.1;
   124	const LOYALTY_DISCOUNT = 0.2;
   125	const LOYALTY_YEARS = 2;
   126	
   127	// Long-standing means at least LOYALTY_YEARS years of business. A discount, so it
   128	// enters the policy-scoped rate as a negative rate.
   129	function loyaltyRate(customer: Customer): number {
   130	  return customer.yearsWithMHPCO >= LOYALTY_YEARS ? -LOYALTY_DISCOUNT : 0;
   131	}
   132	
   133	const FOLLOW_UP_DISCOUNT = 0.15;
   134	
   135	// Every contract after the customer's first earns the follow-up discount.
   136	function followUpRate(previousContracts: number): number {
   137	  return previousContracts > 0 ? -FOLLOW_UP_DISCOUNT : 0;
   138	}
   139	
   140	// The MHPCO's policy-scoped tariff: each recognised policy-wide modifier contributes
   141	// its own rate, and the rates are assessed together against the policy base premium.
   142	//
   143	// MHPCO reading of "a first insurance": the initial assessment is of the items newly
   144	// brought in, not of the customer. Every quote is therefore a first insurance for the
   145	// items it covers, so the surcharge is an unconditional term here -- it consults no
   146	// customer history, and a long-standing customer on a follow-up contract is assessed
   147	// it alongside the loyalty and follow-up discounts rather than instead of them.
   148	function policyScopedRate(customer: Customer, previousContracts: number): number {
   149	  return FIRST_INSURANCE_SURCHARGE + loyaltyRate(customer) + followUpRate(previousContracts);
   150	}
   151	
   152	// Policy-scoped modifiers are assessed against the policy base premium alone -- the
   153	// plain sum of the item base premiums, deliberately excluding item-scoped surcharges.
   154	function policyScopedAdjustment(
   155	  basePremium: number,
   156	  customer: Customer,
   157	  previousContracts: number,
   158	): number {
   159	  return basePremium * policyScopedRate(customer, previousContracts);
   160	}
   161	
   162	const PROCESSING_FEE = 5;
   163	
   164	// Amounts are rounded in the MHPCO's favor, which means opposite directions on the two
   165	// sides of the ledger: a premium the MHPCO collects rounds up, a payout it owes rounds
   166	// down. Both tolerate the same floating-point slack so that an amount computed as
   167	// exactly 197.5 or 350.5 is not pushed across the boundary by representation error.
   168	const AMOUNT_PRECISION = 1e-9;
   169	
   170	function roundUpInMHPCOFavor(amount: number): number {
   171	  return Math.ceil(amount - AMOUNT_PRECISION);
   172	}
   173	
   174	function roundDownInMHPCOFavor(amount: number): number {
   175	  return Math.floor(amount + AMOUNT_PRECISION);
   176	}
   177	
   178	// How the MHPCO closes a premium: the processing fee is added at the very end, after
   179	// every percentage modifier, and only that final figure is rounded -- intermediate
   180	// amounts stay fractional, and rounding always favours the MHPCO.
   181	function closedPremium(modifiedPremium: number): number {
   182	  return roundUpInMHPCOFavor(modifiedPremium + PROCESSING_FEE);
   183	}
   184	
   185	export function quote(customer: Customer, items: Item[], previousContracts: number): number {
   186	  const basePremium = policyBasePremium(items);
   187	  return closedPremium(
   188	    basePremium +
   189	      itemScopedSurcharges(items) +
   190	      policyScopedAdjustment(basePremium, customer, previousContracts),
   191	  );
   192	}
   193	
   194	export interface Damage {
   195	  itemType: string;
   196	  amount: number;
   197	}
   198	
   199	export interface Incident {
   200	  cause: string;
   201	  damages: Damage[];
   202	}
   203	
   204	export interface ClaimSettlement {
   205	  payout: number;
   206	  remainingCap: number;
   207	}
   208	
   209	const DEDUCTIBLE = 100;
   210	const CAP_MULTIPLE = 2;
   211	
   212	// The insurance sum is the plain total of the insured items' values; block discounts and
   213	// premium modifiers affect what the customer pays, never what the policy covers.
   214	function insuranceSum(items: Item[]): number {
   215	  return items.reduce((sum, item) => sum + listedPrice(item.type).insuranceValue, 0);
   216	}
   217	
   218	// The MHPCO pays out at most twice the insurance sum over the life of a policy.
   219	function policyCap(items: Item[]): number {
   220	  return CAP_MULTIPLE * insuranceSum(items);
   221	}
   222	
   223	const HALVED_ENCHANTMENT_LEVEL = 8;
   224	const HALVED_REIMBURSEMENT = 0.5;
   225	
   226	// Which insured items the MHPCO considers too enchanted to reimburse in full.
   227	function isEnchantedEnoughToHalve(insured: Item): boolean {
   228	  return enchantmentLevel(insured) >= HALVED_ENCHANTMENT_LEVEL;
   229	}
   230	
   231	// How much of a reported damage the MHPCO recognises before the deductible: a special
   232	// clause can reduce the recognised amount, and absent any clause the full damage counts.
   233	//
   234	// The dragon-material clause is deliberately absent rather than forgotten. "Damage to items
   235	// made of dragon material is fully reimbursed" grants exactly what every unclassified item
   236	// already gets here -- full recognition -- so on its own it is indistinguishable from the
   237	// default, and where it meets the halving clause the halving clause wins. Dragon material
   238	// therefore never changes a recognised amount: it is subsumed by the default when it
   239	// applies alone and overridden when it does not. A branch for it would be unreachable by
   240	// any observation, so the clause is recorded here instead of being coded. Should the MHPCO
   241	// ever grant dragon material more than full reimbursement, the clause becomes observable
   242	// and earns a branch -- and a precedence decision against halving -- at that point.
   243	function reimbursableDamage(damage: Damage, insured: Item): number {
   244	  if (isEnchantedEnoughToHalve(insured)) {
   245	    return damage.amount * HALVED_REIMBURSEMENT;
   246	  }
   247	  return damage.amount;
   248	}
   249	
   250	// Each damage event bears its own deductible, and the MHPCO never pays less than nothing.
   251	function reimbursement(damage: Damage, insured: Item): number {
   252	  return Math.max(reimbursableDamage(damage, insured) - DEDUCTIBLE, 0);
   253	}
   254	
   255	// One reported damage, admitted against the single insured item it is settled on.
   256	interface AdmittedDamage {
   257	  damage: Damage;
   258	  insured: Item;
   259	}
   260	
   261	// Whether a reported damage is a damage report the MHPCO can read at all. A report states
   262	// how much harm was done, so a negative amount leaves nothing to assess -- the office
   263	// declines the paperwork rather than the cover. This question consults no policy, no price
   264	// list and no insured item, which is why it is settled on the whole report before admission
   265	// looks anything up: an unreadable entry is refused at intake, and a claim carrying one is
   266	// declined on that ground even where it also names an item the policy does not cover.
   267	function validateReport(damages: Damage[]): void {
   268	  for (const damage of damages) {
   269	    if (damage.amount < 0) {
   270	      throw new Error(`MHPCO cannot assess a damage amount of ${damage.amount}`);
   271	    }
   272	  }
   273	}
   274	
   275	// Who the MHPCO admits to a claim. A damage entry names an insured item by type, and each
   276	// entry is settled on an item of its own: the policy covers one damage per insured item,
   277	// so two entries naming the same type need two such items on the policy. An entry that
   278	// finds no item left to settle on is declined, and with it the whole claim, before any
   279	// damage is valued. Which insured item of a matching type an entry is settled on is left
   280	// unstated: the MHPCO takes them in the order the policy lists them.
   281	//
   282	// This one rule is the whole of the office's claim admission, and it declines on a single
   283	// ground -- no insured item left for this entry. Every way a claim can name an item the
   284	// MHPCO will not settle reduces to that ground: a type the policy does not cover at all, a
   285	// type claimed more often than the policy covers it, and a type the MHPCO does not insure
   286	// anywhere. The last needs no price-list check of its own on the claim path: the policy's
   287	// items were all priced through listedPrice when it was quoted, so an uninsurable type can
   288	// never appear among them, and an entry naming one finds nothing to match for that reason.
   289	// Admission therefore asks only what the policy covers, and stays correct when the price
   290	// list grows or shrinks. Whether a reported damage is a well-formed report in the first
   291	// place -- its amount, say -- is a separate question that consults no policy at all.
   292	function admitDamages(damages: Damage[], items: Item[]): AdmittedDamage[] {
   293	  const unsettled = [...items];
   294	  return damages.map((damage) => {
   295	    const index = unsettled.findIndex((item) => item.type === damage.itemType);
   296	    if (index === -1) {
   297	      throw new Error(`MHPCO policy does not cover a further "${damage.itemType}" to claim for`);
   298	    }
   299	    return { damage, insured: unsettled.splice(index, 1)[0] };
   300	  });
   301	}
   302	
   303	// What the MHPCO owes for one incident: every admitted damage valued on its own and summed.
   304	function incidentReimbursement(damages: Damage[], items: Item[]): number {
   305	  return admitDamages(damages, items).reduce(
   306	    (total, { damage, insured }) => total + reimbursement(damage, insured),
   307	    0,
   308	  );
   309	}
   310	
   311	// How the MHPCO closes a claim against its cap. The cap is a lifetime limit on the policy,
   312	// so what this settlement may pay is bounded by what the cap had left beforehand -- the
   313	// cap less everything the policy has already paid out. An over-cap claim is trimmed to the
   314	// remainder rather than declined: the customer is paid what is left and the cap closes at
   315	// zero. Whether a claim may exceed its remaining cap, and by what rule, is the MHPCO's own
   316	// decision and moves independently of how a damage is valued.
   317	function cappedSettlement(desired: number, remainingBefore: number): ClaimSettlement {
   318	  const payout = Math.min(desired, remainingBefore);
   319	  return { payout, remainingCap: remainingBefore - payout };
   320	}
   321	
   322	// How the MHPCO settles one claim against one policy: the report is read for
   323	// well-formedness before anything is looked up, then valued against the policy, then
   324	// closed against what the cap has left. The three steps answer questions that move
   325	// independently of one another, so the office's one operation sequences them in the
   326	// order its clerks work rather than nesting one inside another.
   327	export function claim(items: Item[], incident: Incident, alreadyPaid = 0): ClaimSettlement {
   328	  validateReport(incident.damages);
   329	  return cappedSettlement(
   330	    roundDownInMHPCOFavor(incidentReimbursement(incident.damages, items)),
   331	    policyCap(items) - alreadyPaid,
   332	  );
   333	}
   334	
   335	export interface QuoteStep {
   336	  op: "quote";
   337	  items: Item[];
   338	}
   339	
   340	export interface ClaimStep {
   341	  op: "claim";
   342	  policy: number;
   343	  incident: Incident;
   344	}
   345	
   346	export type Step = QuoteStep | ClaimStep;
   347	
   348	// A policy the scenario has issued: the items it covers and what it has paid out so far,
   349	// because the cap is a lifetime limit across the policy's successive claims.
   350	interface Policy {
   351	  items: Item[];
   352	  paidOut: number;
   353	}
   354	
   355	export interface Scenario {
   356	  customer: Customer;
   357	  steps: Step[];
   358	}
   359	
   360	export type StepResult = { premium: number } | ClaimSettlement;
   361	
   362	export interface ScenarioResults {
   363	  results: StepResult[];
   364	}
   365	
   366	// A claim against an issued policy, charged to that policy's record. The cap is a lifetime
   367	// limit, so the policy's own running total is both what bounds this settlement and what the
   368	// settlement adds to -- one decision, read and written together.
   369	function settleAgainstPolicy(policy: Policy, incident: Incident): ClaimSettlement {
   370	  const settlement = claim(policy.items, incident, policy.paidOut);
   371	  policy.paidOut += settlement.payout;
   372	  return settlement;
   373	}
   374	
   375	// A claim can only be made against a policy an earlier quote step actually issued. The
   376	// policy register is addressed by the step index that issued the policy, which is how a
   377	// claim step names the cover it is claiming against.
   378	function issuedPolicy(policies: Map<number, Policy>, index: number): Policy {
   379	  const policy = policies.get(index);
   380	  if (policy === undefined) {
   381	    throw new Error(`MHPCO has no policy issued by step ${index} to claim against`);
   382	  }
   383	  return policy;
   384	}
   385	
   386	// The scenario clerk: one customer's steps worked in the order they were filed. Each quote
   387	// is a further contract for that customer, so every quote after the first earns the follow-up
   388	// discount, and each one leaves a policy in the register under its own step index for later
   389	// claim steps to name.
   390	export function runScenario(scenario: Scenario): ScenarioResults {
   391	  const results: StepResult[] = [];
   392	  const policies = new Map<number, Policy>();
   393	  let contractsSoFar = 0;
   394	  scenario.steps.forEach((step, index) => {
   395	    if (step.op === "quote") {
   396	      results.push({ premium: quote(scenario.customer, step.items, contractsSoFar) });
   397	      contractsSoFar += 1;
   398	      policies.set(index, { items: step.items, paidOut: 0 });
   399	    } else {
   400	      results.push(settleAgainstPolicy(issuedPolicy(policies, step.policy), step.incident));
   401	    }
   402	  });
   403	  return { results };
   404	}

